/**
 * Module intro videos (built by tools/video — see tools/video/README.md).
 * Generated by tools/video/sync-videos.mjs: moduleId -> file stem in public/videos/ and running time.
 */
const videos = {
  architecture: { file: 'm01-architecture', length: '2:18' },
  development: { file: 'm02-development', length: '2:17' },
  evaluation: { file: 'm03-evaluation', length: '2:18' },
  deployment: { file: 'm04-deployment', length: '2:11' },
  cognition: { file: 'm05-cognition', length: '2:09' },
  knowledge: { file: 'm06-knowledge', length: '2:16' },
  platform: { file: 'm07-platform', length: '2:22' },
  operations: { file: 'm08-operations', length: '2:21' },
  safety: { file: 'm09-safety', length: '2:20' },
  human: { file: 'm10-human', length: '2:18' },
}

export function moduleVideo(moduleId) {
  const v = videos[moduleId]
  if (!v) return null
  const base = `${import.meta.env.BASE_URL}videos/${v.file}`
  return { ...v, mp4: `${base}.mp4`, vtt: `${base}.vtt`, poster: `${base}.jpg` }
}
